private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    try {
        if (i < 0 || i >= bb.limit()) {
            return i;
        }
        int b0 = bb.get(i) & 0xFF;
        int len;
        if ((b0 & 0x80) == 0) {
            len = 1;
        } else if ((b0 & 0xE0) == 0xC0) {
            len = 2;
        } else if ((b0 & 0xF0) == 0xE0) {
            len = 3;
        } else if ((b0 & 0xF8) == 0xF0) {
            len = 4;
        } else {
            // invalid first byte
            return i;
        }
        if (i + len > bb.limit()) {
            return i;
        }
        // Validate continuation bytes
        for (int j = 1; j < len; j++) {
            int b = bb.get(i + j) & 0xFF;
            if ((b & 0xC0) != 0x80) {
                return i;
            }
        }
        byte[] arr = new byte[len];
        for (int j = 0; j < len; j++) {
            arr[j] = bb.get(i + j);
        }
        sb.append(new String(arr, java.nio.charset.StandardCharsets.UTF_8));
        return i + len;
    } catch (Exception e) {
        return i;
    }
}

