public long readLong(final int offset){
    if (offset < 0 || offset + 8 > this.data.length) {
        throw new IndexOutOfBoundsException("offset out of bounds");
    }
    return ((long)(this.data[offset] & 0xFF) << 56)
        | ((long)(this.data[offset + 1] & 0xFF) << 48)
        | ((long)(this.data[offset + 2] & 0xFF) << 40)
        | ((long)(this.data[offset + 3] & 0xFF) << 32)
        | ((long)(this.data[offset + 4] & 0xFF) << 24)
        | ((long)(this.data[offset + 5] & 0xFF) << 16)
        | ((long)(this.data[offset + 6] & 0xFF) << 8)
        | ((long)(this.data[offset + 7] & 0xFF));
}

