static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day = (int)(timeBucket % 100);
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket");
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket");
    }
    int newDay = 1 + ((day - 1) / dayStep) * dayStep;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        return 0;
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("index: " + index + ", len: " + len + ", str.length: " + strLen);
    }
    int end = index + len;
    int i = index;
    int size = 0;
    while (i < end) {
        int cp = str.codePointAt(i);
        int cpLen = Character.charCount(cp);
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
        i += cpLen;
    }
    return size;
}

