public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength <= 0) {
        return this;
    }
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
    }
    int loc0 = this.length;
    if (loc0 + byteLength > this.data.length) {
        enlarge(byteLength);
    }
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            this.data[loc0 + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.data, loc0, byteLength);
    }
    this.length = loc0 + byteLength;
    return this;
}

