public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (lb == null) {
        return null;
    }
    if (str == null) {
        return lb;
    }
    try {
        byte[] bytes = str.toString().getBytes("UTF-8");
        if (session != null) {
            // Attempt to write via the session if it provides a write method
            session.write(bytes, 0, bytes.length);
        } else {
            // Fallback to writing directly into the LinkedBuffer
            lb.write(bytes, 0, bytes.length);
        }
    } catch (Exception e) {
        // Suppress any encoding or I/O exceptions
    }
    return lb;
}

