private boolean containsAllFields(Fields fields) {
    if (fields == null) {
        return false;
    }
    try {
        // Attempt to get a collection of field names
        java.lang.reflect.Method getNames = fields.getClass().getMethod("getFieldNames");
        Object namesObj = getNames.invoke(fields);
        if (namesObj instanceof java.util.Collection) {
            for (Object name : (java.util.Collection<?>) namesObj) {
                if (!(name instanceof String)) {
                    return false;
                }
                if (!properties.containsKey((String) name)) {
                    return false;
                }
            }
            return true;
        }
    } catch (Exception ignored) {
        // ignore and try other strategies
    }
    try {
        // Attempt to get a collection of Field objects
        java.lang.reflect.Method getFields = fields.getClass().getMethod("getFields");
        Object fieldsObj = getFields.invoke(fields);
        if (fieldsObj instanceof java.util.Collection) {
            for (Object f : (java.util.Collection<?>) fieldsObj) {
                if (f instanceof java.lang.reflect.Field) {
                    java.lang.reflect.Field field = (java.lang.reflect.Field) f;
                    if (!properties.containsKey(field.getName())) {
                        return false;
                    }
                } else {
                    return false;
                }
            }
            return true;
        }
    } catch (Exception ignored) {
        // ignore and try other strategies
    }
    // Fallback: if Fields implements Iterable
    if (fields instanceof java.lang.Iterable) {
        for (Object obj : (java.lang.Iterable<?>) fields) {
            if (obj instanceof java.lang.reflect.Field) {
                java.lang.reflect.Field field = (java.lang.reflect.Field) obj;
                if (!properties.containsKey(field.getName())) {
                    return false;
                }
            } else if (obj instanceof String) {
                if (!properties.containsKey((String) obj)) {
                    return false;
                }
            } else {
                return false;
            }
        }
        return true;
    }
    return false;
}

