public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Trailing backslash");
            }
            char next = str.charAt(++i);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= str.length()) {
                        throw new Exception("Incomplete unicode escape");
                    }
                    String hex = str.substring(i + 1, i + 5);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape: \\u" + hex);
                    }
                    i += 4;
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i;
                        int oct = next - '0';
                        int count = 1;
                        while (count < 3 && j + 1 < str.length()
                                && str.charAt(j + 1) >= '0' && str.charAt(j + 1) <= '7') {
                            oct = (oct << 3) + (str.charAt(++j) - '0');
                            count++;
                        }
                        sb.append((char) oct);
                        i = j;
                    } else {
                        throw new Exception("Unknown escape sequence: \\" + next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

