final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index");
    }
    // Skip the tag byte
    int offset = constantPoolEntryIndex + 1;
    if (offset + 1 >= classFileBuffer.length) {
        throw new IllegalArgumentException("Malformed constant pool entry");
    }
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
    int stringStart = offset + 2;
    if (stringStart + length > classFileBuffer.length) {
        throw new IllegalArgumentException("Malformed constant pool entry");
    }
    String result = new String(classFileBuffer, stringStart, length, StandardCharsets.UTF_8);
    if (charBuffer != null && charBuffer.length >= result.length()) {
        result.getChars(0, result.length(), charBuffer, 0);
    }
    return result;
}

