        Type firstBound = bounds[0];
        return firstBound != null ? firstBound : Unknown.class;
    } catch (Exception e) {
        return Unknown.class;
    }
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
