}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    TreeSet<Integer> set = new TreeSet<>();
    for (K k : keys){
        if (k == null) continue;
        try{
            set.add((Integer)k);
        } catch (ClassCastException e){
            // skip non-integer keys
        }
    }
    for (K k : keys){
        if (k == null){
            result.add(null);
            continue;
        }
        Integer keyInt;
        try{
            keyInt = (Integer)k;
        } catch (ClassCastException e){
            result.add(null);
            continue;
        }
        Integer lower = set.floor(keyInt);
        result.add(lower);
    }
    return result;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
            continue;
        }
        try {
            if (key instanceof Integer) {
                bounds.add((Integer) key);
            } else if (key instanceof Number) {
                bounds.add(((Number) key).intValue());
            } else {
                bounds.add(key.hashCode());
            }
        } catch (Exception e) {
            bounds.add(0);
        }
    }
    return bounds;
}

