public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    // If the relative path is actually absolute, return it as is
    if (relativePath.startsWith("/")) {
        return relativePath;
    }
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();
    boolean leadingSlash = path.startsWith("/");
    String[] baseParts = path.split("/");
    for (String part : baseParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }
    StringBuilder sb = new StringBuilder();
    if (leadingSlash) {
        sb.append("/");
    }
    java.util.Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    if (sb.length() == 0 && leadingSlash) {
        return "/";
    }
    return sb.toString();
}

