static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        return (String[]) array;
    }
    int newSize = array.length - nullCount;
    String[] result = new String[newSize];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
