    try {
        int dotIndex = filename.lastIndexOf('.');
        if (dotIndex == -1) return -1;
        int sepIndex = indexOfLastSeparator(filename);
        if (sepIndex > dotIndex) return -1;
        return dotIndex;
    } catch (Exception e) {
        return -1;
    }
}

