        long start = this.contentRangeStart;
        long end   = this.contentRangeEnd;
        long total = this.contentRangeTotal;
        if(start < 0 || end < 0){
            throw new IllegalArgumentException("Content range start and end must be non‑negative");
        }
        if(end < start){
            throw new IllegalArgumentException("Content range end must be greater than or equal to start");
        }
        StringBuilder sb = new StringBuilder();
        sb.append("bytes ");
        sb.append(start).append('-').append(end);
        sb.append('/');
        sb.append(total > 0 ? total : '*');
        return sb.toString();
    }catch(Exception e){
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null) {
        return snapshots;
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
            if (snapshot == null) {
                continue;
            }
            if (timeRanges == null || timeRanges.isEmpty()) {
                snapshots.add(snapshot);
            } else {
                long ts = snapshot.getTimestamp();
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    long start = range.getStartMillis();
                    long end = range.getEndMillis();
                    if (ts >= start && ts <= end) {
                        snapshots.add(snapshot);
                        break;
                    }
                }
            }
        }
    }
    return snapshots;
}
